const el = document.getElementById('jz3d-canvas-wrap');
if (el && window.THREE_READY !== false) {
  const W = () => el.clientWidth, H = () => el.clientHeight || 520;
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf4f8f8);
  scene.fog = new THREE.Fog(0xf4f8f8, 9000, 26000);

  const camera = new THREE.PerspectiveCamera(46, W() / H(), 10, 60000);
  camera.position.set(5200, 5800, 10400);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(W(), H());
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  el.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.set(650, 0, 4870);
  controls.maxPolarAngle = Math.PI / 2.05;
  controls.minDistance = 800; controls.maxDistance = 24000;

  scene.add(new THREE.HemisphereLight(0xffffff, 0xb8c8c8, 1.05));
  const sun = new THREE.DirectionalLight(0xffffff, 1.4);
  sun.position.set(6000, 9000, 4000);
  scene.add(sun);

  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  scene.add(group);

  // ground site slab
  const siteShape = new THREE.Shape(D.site.map(p => new THREE.Vector2(p[0], p[1])));
  const ground = new THREE.Mesh(
    new THREE.ExtrudeGeometry(siteShape, { depth: 12, bevelEnabled: false }),
    new THREE.MeshLambertMaterial({ color: 0xeef2ee })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -12;
  group.add(ground);

  // land-use parcels (thin colored slabs)
  const luGroup = new THREE.Group();
  for (const p of D.parcels) {
    let pts = p.ring.map(q => new THREE.Vector2(q[0], q[1]));
    if (pts.length < 3) continue;
    const sh = new THREE.Shape(pts);
    let geo;
    try { geo = new THREE.ExtrudeGeometry(sh, { depth: 8, bevelEnabled: false }); } catch (e) { continue; }
    const m = new THREE.Mesh(geo, new THREE.MeshLambertMaterial({ color: p.c, transparent: true, opacity: 0.85 }));
    m.rotation.x = -Math.PI / 2;
    m.position.y = 2;
    luGroup.add(m);
  }
  group.add(luGroup);

  // conceptual buildings
  const bldMat = new THREE.MeshLambertMaterial({ color: 0x3a6470 });
  for (const b of D.buildings) {
    const w = Math.max(b.w, 30), d = Math.max(b.d, 30);
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, b.h, d), bldMat);
    m.position.set(b.pos[0], b.h / 2, b.pos[1]);
    group.add(m);
  }

  // green spine ribbon
  if (D.spine && D.spine.length > 1) {
    const curve = new THREE.CatmullRomCurve3(D.spine.map(p => new THREE.Vector3(p[0], 16, p[1])));
    const tube = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 72, 52, 8, false),
      new THREE.MeshLambertMaterial({ color: 0x17b8a6, emissive: 0x0a5a50, emissiveIntensity: 0.45 })
    );
    group.add(tube);
  }

  // label sprite (canvas texture)
  function makeLabel(text) {
    const cv = document.createElement('canvas');
    cv.width = 512; cv.height = 128;
    const ctx = cv.getContext('2d');
    ctx.fillStyle = 'rgba(255,255,255,0.94)';
    ctx.strokeStyle = '#2E5E6E'; ctx.lineWidth = 4;
    ctx.beginPath();
    if (ctx.roundRect) { ctx.roundRect(6, 6, 500, 116, 18); } else { ctx.rect(6, 6, 500, 116); }
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#1E2A2E';
    ctx.font = 'bold 44px "PingFang SC", "Microsoft YaHei", sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, 256, 66);
    const tex = new THREE.CanvasTexture(cv);
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false }));
    sp.scale.set(1500, 375, 1);
    return sp;
  }

  // three stations (extruded blocks + labels)
  const pickables = [];
  for (const s of D.stations) {
    const block = new THREE.Mesh(
      new THREE.BoxGeometry(Math.max(s.size[0] * 0.95, 520), s.h * 6, Math.max(s.size[1] * 0.62, 520)),
      new THREE.MeshLambertMaterial({ color: s.color, transparent: true, opacity: 0.9 })
    );
    block.position.set(s.pos[0], s.h * 6 / 2 + 8, s.pos[1]);
    block.userData = { name: s.name, info: s.info, kind: 'station' };
    group.add(block);
    pickables.push(block);
    const lbl = makeLabel(s.name);
    lbl.position.set(s.pos[0], s.h * 6 + 460, s.pos[1]);
    group.add(lbl);
  }

  // six crossings (amber pillars + rings)
  const pillarMat = new THREE.MeshLambertMaterial({ color: 0xc77d2e, emissive: 0x7a4310, emissiveIntensity: 0.5 });
  for (const c of D.crossings) {
    const pillar = new THREE.Mesh(new THREE.CylinderGeometry(32, 32, 560, 12), pillarMat);
    pillar.position.set(c.pos[0], 280, c.pos[1]);
    pillar.userData = { name: c.name, info: c.info, kind: 'crossing' };
    group.add(pillar);
    pickables.push(pillar);
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(105, 14, 8, 28),
      new THREE.MeshBasicMaterial({ color: 0xc77d2e })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(c.pos[0], 8, c.pos[1]);
    group.add(ring);
  }

  // legend / info panel (HTML overlay)
  const panel = document.getElementById('jz3d-info');
  const panelTitle = document.getElementById('jz3d-info-title');
  const panelBody = document.getElementById('jz3d-info-body');
  function showInfo(userData) {
    if (!panel) return;
    panelTitle.textContent = userData.name;
    panelBody.textContent = userData.info;
    panel.style.display = 'block';
  }
  const ray = new THREE.Raycaster();
  const mouse = new THREE.Vector2();
  let downXY = null;
  renderer.domElement.addEventListener('pointerdown', e => { downXY = [e.clientX, e.clientY]; });
  renderer.domElement.addEventListener('pointerup', e => {
    if (!downXY) return;
    const dx = e.clientX - downXY[0], dy = e.clientY - downXY[1];
    downXY = null;
    if (dx * dx + dy * dy > 25) return; // drag, not click
    const r = renderer.domElement.getBoundingClientRect();
    mouse.x = ((e.clientX - r.left) / r.width) * 2 - 1;
    mouse.y = -((e.clientY - r.top) / r.height) * 2 + 1;
    ray.setFromCamera(mouse, camera);
    const hit = ray.intersectObjects(pickables, false)[0];
    if (hit) showInfo(hit.object.userData);
  });

  // resize
  window.addEventListener('resize', () => {
    camera.aspect = W() / H();
    camera.updateProjectionMatrix();
    renderer.setSize(W(), H());
  });

  // animate
  (function loop() {
    requestAnimationFrame(loop);
    controls.update();
    renderer.render(scene, camera);
  })();
}
